;\n    margin-top: -@font-size-sm / 2;\n    color: @disabled-color;\n    font-size: @font-size-sm;\n    line-height: 1;\n    transform-origin: 50% 50%;\n\n    & &-icon svg {\n      transition: transform 0.3s;\n    }\n  }\n\n  &-selection {\n    display: block;\n    box-sizing: border-box;\n    background-color: @select-background;\n    border: @border-width-base @border-style-base @select-border-color;\n    // strange align fix for chrome but works\n    // https://gw.alipayobjects.com/zos/rmsportal/VFTfKXJuogBAXcvfAUWJ.gif\n    border-top-width: @border-width-base + 0.02px;\n    border-radius: @border-radius-base;\n    outline: none;\n    transition: all 0.3s @ease-in-out;\n    user-select: none;\n\n    &:hover {\n      .hover;\n    }\n\n    .@{select-prefix-cls}-focused &,\n    &:focus,\n    &:active {\n      .active;\n    }\n\n    &__clear {\n      .selection__clear();\n    }\n\n    &:hover &__clear {\n      opacity: 1;\n    }\n\n    &-selected-value {\n      float: left;\n      max-width: 100%;\n      overflow: hidden;\n      white-space: nowrap;\n      text-overflow: ellipsis;\n    }\n  }\n\n  &-no-arrow &-selection-selected-value {\n    padding-right: 0;\n  }\n\n  &-disabled {\n    color: @disabled-color;\n  }\n\n  &-disabled &-selection {\n    background: @input-disabled-bg;\n    cursor: not-allowed;\n    &:hover,\n    &:focus,\n    &:active {\n      border-color: @select-border-color;\n      box-shadow: none;\n    }\n\n    &__clear {\n      display: none;\n      visibility: hidden;\n      pointer-events: none;\n    }\n  }\n\n  &-disabled &-selection--multiple &-selection__choice {\n    padding-right: 10px;\n    color: fade(@black, 33%);\n    background: @background-color-base;\n    &__remove {\n      display: none;\n    }\n  }\n\n  &-selection--single {\n    position: relative;\n    height: @input-height-base;\n    cursor: pointer;\n\n    .@{select-prefix-cls}-selection__rendered {\n      margin-right: 24px;\n    }\n  }\n\n  &-no-arrow {\n    .@{select-prefix-cls}-selection__rendered {\n      margin-right: @control-padding-horizontal - 1px;\n    }\n  }\n\n  &-selection__rendered {\n    position: relative;\n    display: block;\n    margin-right: @control-padding-horizontal - 1px;\n    margin-left: @control-padding-horizontal - 1px;\n    line-height: @input-height-base - 2px;\n    // https://github.com/ant-design/ant-design/issues/3481#issuecomment-254721026\n    &::after {\n      display: inline-block;\n      width: 0;\n      visibility: hidden;\n      content: '.';\n      pointer-events: none;\n    }\n  }\n\n  &-lg {\n    font-size: @font-size-lg;\n    .@{select-prefix-cls}-selection--single {\n      height: @input-height-lg;\n    }\n    .@{select-prefix-cls}-selection__rendered {\n      line-height: @input-height-lg - 2px;\n    }\n    .@{select-prefix-cls}-selection--multiple {\n      min-height: @input-height-lg;\n      .@{select-prefix-cls}-selection__rendered {\n        li {\n          height: @input-height-lg - 8px;\n          line-height: @input-height-lg - 8px;\n        }\n      }\n      .@{select-prefix-cls}-selection__clear,\n      .@{select-prefix-cls}-arrow {\n        top: @input-height-lg / 2;\n      }\n    }\n  }\n\n  &-sm {\n    .@{select-prefix-cls}-selection--single {\n      height: @input-height-sm;\n    }\n    .@{select-prefix-cls}-selection__rendered {\n      margin-left: @control-padding-horizontal-sm - 1px;\n      line-height: @input-height-sm - 2px;\n    }\n    .@{select-prefix-cls}-selection--multiple {\n      min-height: @input-height-sm;\n      .@{select-prefix-cls}-selection__rendered {\n        li {\n          height: @input-height-sm - 8px;\n          line-height: @input-height-sm - 10px;\n        }\n      }\n      .@{select-prefix-cls}-selection__clear,\n      .@{select-prefix-cls}-arrow {\n        top: @input-height-sm / 2;\n      }\n    }\n    .@{select-prefix-cls}-selection__clear,\n    .@{select-prefix-cls}-arrow {\n      right: @control-padding-horizontal-sm;\n    }\n  }\n\n  &-disabled